import json
import hashlib
import hmac
import os
import re
import time
from urllib.parse import parse_qs
from http.server import HTTPServer, BaseHTTPRequestHandler

# Configuration
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
DB_COLLECTIONS = {}

# Maximum allowed token age in seconds (tokens older than this are rejected)
TOKEN_MAX_AGE_SECONDS = 3600


class SecureQueryBuilder:
    """Builds safe database queries with strict input sanitization."""

    ALLOWED_COMPARISON_OPS = frozenset([
        '$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin'
    ])

    def __init__(self, collection_name):
        self.collection = collection_name
        self.filters = {}
        self._audit_log = []

    def sanitize_value(self, value):
        """Ensure values are safe scalar types only."""
        if isinstance(value, str):
            return value
        elif isinstance(value, (int, float)):
            return value
        elif isinstance(value, bool):
            return value
        elif value is None:
            return None
        else:
            raise ValueError(f"Unsupported value type: {type(value)}")

    def add_filter(self, field, value):
        """Add a filter condition to the query."""
        # Validate field name - strict alphanumeric with dots for nesting
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_.]*$', field):
            raise ValueError(f"Invalid field name: {field}")
        if field.startswith('$'):
            raise ValueError("Field names cannot start with $")

        # Only allow scalar values - no dicts, no operators from user input
        sanitized = self.sanitize_value(value)
        self.filters[field] = {'$eq': sanitized}
        self._audit_log.append(('filter', field, repr(sanitized)))
        return self

    def add_range_filter(self, field, op, value):
        """Add a comparison filter with explicit operator."""
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_.]*$', field):
            raise ValueError(f"Invalid field name: {field}")
        if op not in self.ALLOWED_COMPARISON_OPS:
            raise ValueError(f"Operator {op} not allowed")

        sanitized = self.sanitize_value(value)
        self.filters[field] = {op: sanitized}
        self._audit_log.append(('range_filter', field, op, repr(sanitized)))
        return self

    def add_in_filter(self, field, values):
        """Add an $in filter with validated scalar values."""
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_.]*$', field):
            raise ValueError(f"Invalid field name: {field}")

        sanitized_values = [self.sanitize_value(v) for v in values]
        self.filters[field] = {'$in': sanitized_values}
        self._audit_log.append(('in_filter', field, repr(sanitized_values)))
        return self

    def build(self):
        """Build the final query document."""
        return dict(self.filters)


def parse_scalar_value(raw_value):
    """Parse a query parameter value as a scalar only.

    Never parses JSON objects or arrays from user input.
    Only converts to numeric types if unambiguous.
    """
    if not raw_value:
        return ''

    # Try numeric conversion only
    try:
        if '.' in raw_value:
            return float(raw_value)
        return int(raw_value)
    except ValueError:
        pass

    # Return as plain string - never parse as JSON
    return raw_value


def authenticate_request(headers):
    """Verify request authentication token."""
    auth_header = headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return None

    token = auth_header[7:]
    parts = token.split('.')
    if len(parts) != 3:
        return None

    payload_b64, timestamp, signature = parts

    # Verify signature using proper HMAC
    key = SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode()
    expected = hmac.new(
        key,
        f"{payload_b64}.{timestamp}".encode(),
        hashlib.sha256
    ).hexdigest()

    if not hmac.compare_digest(signature, expected):
        return None

    # Enforce token expiry to prevent indefinitely valid / replayed tokens.
    try:
        issued_at = int(timestamp)
    except (ValueError, TypeError):
        return None
    now = int(time.time())
    if issued_at > now + 60:  # reject tokens issued in the future (clock skew allowance)
        return None
    if now - issued_at > TOKEN_MAX_AGE_SECONDS:
        return None

    try:
        payload = json.loads(
            __import__('base64').b64decode(payload_b64 + '==').decode()
        )
        return payload
    except Exception:
        return None


class QueryHandler(BaseHTTPRequestHandler):

    def do_GET(self):
        """Handle search queries."""
        if '?' not in self.path:
            self.send_error(400, "Missing query parameters")
            return

        path, query_string = self.path.split('?', 1)

        # Extract collection from path
        path_parts = path.strip('/').split('/')
        if len(path_parts) < 2 or path_parts[0] != 'api':
            self.send_error(404, "Not found")
            return

        collection = path_parts[1]
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', collection):
            self.send_error(400, "Invalid collection name")
            return

        # Parse query parameters
        params = parse_qs(query_string, keep_blank_values=True)

        # Build query with strict scalar-only parsing
        builder = SecureQueryBuilder(collection)

        try:
            for field, values in params.items():
                if field.startswith('_'):
                    continue  # Skip meta-parameters

                if len(values) > 1:
                    # Multiple values for same param -> $in query
                    typed_values = [parse_scalar_value(v) for v in values]
                    builder.add_in_filter(field, typed_values)
                else:
                    typed_value = parse_scalar_value(values[0])
                    builder.add_filter(field, typed_value)

            query = builder.build()

            # Execute query (simulated)
            results = self._execute_query(collection, query)

            # Filter sensitive fields from output
            safe_results = []
            for doc in results:
                safe_doc = {k: v for k, v in doc.items() 
                           if k not in ('password_hash', '_internal')}
                safe_results.append(safe_doc)

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({
                'results': safe_results,
                'count': len(safe_results)
            }).encode())

        except ValueError as e:
            self.send_error(400, str(e))

    def _execute_query(self, collection, query):
        """Execute query against in-memory data."""
        data = DB_COLLECTIONS.get(collection, [])
        results = []

        for doc in data:
            if self._matches(doc, query):
                results.append(doc)

        return results

    def _matches(self, doc, query):
        """Check if document matches query filters."""
        for field, condition in query.items():
            doc_value = self._get_nested(doc, field)

            if isinstance(condition, dict):
                for op, op_value in condition.items():
                    if op == '$eq' and doc_value != op_value:
                        return False
                    elif op == '$ne' and doc_value == op_value:
                        return False
                    elif op == '$gt' and not (doc_value is not None and doc_value > op_value):
                        return False
                    elif op == '$gte' and not (doc_value is not None and doc_value >= op_value):
                        return False
                    elif op == '$lt' and not (doc_value is not None and doc_value < op_value):
                        return False
                    elif op == '$lte' and not (doc_value is not None and doc_value <= op_value):
                        return False
                    elif op == '$in' and doc_value not in op_value:
                        return False
                    elif op == '$nin' and doc_value in op_value:
                        return False
            else:
                if doc_value != condition:
                    return False

        return True

    def _get_nested(self, doc, field):
        """Get nested field value using dot notation."""
        parts = field.split('.')
        current = doc
        for part in parts:
            if isinstance(current, dict):
                current = current.get(part)
            else:
                return None
        return current


